const tweets = [
  'Какой-то странный тред',
  'Твит, адресованный Илону Маску',
  'Ответ на инфоповод'
];

function forEach(arr, callback) {
  for (let index = 0; index < arr.length; index++) {
    if (index in arr) callback(arr[index], index, arr);
  }
}

forEach(tweets, function (tweet) {
	console.log(tweet);
});
